"""Longest Duplicate Substring — binary search the length + Rabin-Karp.

If a duplicate of length L exists then so does one of every shorter length, so
the predicate is monotonic and binary search applies. Each check rolls a
polynomial hash over the string in linear time.

Time: O(n log n) expected   Space: O(n)
"""


class Solution:
    def longestDupSubstring(self, s: str) -> str:
        n = len(s)
        nums = [ord(c) - ord("a") for c in s]
        base, mod = 26, (1 << 61) - 1

        def search(length: int):
            if length == 0:
                return 0
            high = pow(base, length, mod)
            rolling = 0
            for i in range(length):
                rolling = (rolling * base + nums[i]) % mod
            seen = {rolling: [0]}
            for i in range(1, n - length + 1):
                rolling = (rolling * base - nums[i - 1] * high + nums[i + length - 1]) % mod
                if rolling in seen:
                    current = s[i:i + length]
                    for j in seen[rolling]:          # guard against collisions
                        if s[j:j + length] == current:
                            return i
                    seen[rolling].append(i)
                else:
                    seen[rolling] = [i]
            return -1

        lo, hi, start, best = 1, n - 1, 0, 0
        while lo <= hi:
            mid = (lo + hi) // 2
            pos = search(mid)
            if pos != -1:
                start, best = pos, mid
                lo = mid + 1
            else:
                hi = mid - 1
        return s[start:start + best]
